  "kaynak": "舊唐書 juan 198 (zh.wikisource.org/wiki/舊唐書/卷198; bu oturumda okundu): «則天臨朝，長壽元年，武威軍總管王孝傑、阿史那忠節大破吐蕃，克復龜茲、於闐等四鎮» | 舊唐書 juan 6 (zh.wikisource.org/wiki/舊唐書/卷6; bu oturumda okundu): «冬十月，武威軍總管王孝傑大破吐蕃，復龜茲、于闐、疏勒、碎葉鎮。» | 舊唐書 juan 196下 (zh.wikisource.org/wiki/舊唐書/卷196下; bu oturumda okundu): «自是安西阻絕，莫知存否。» | BEYAN: t=0791-01-01 yıl (貞元七年 ≈ 791; yıl numarası sayfa bağlamından, ay/gün yok): Beiting 790’da düştü, Anxi (Dört Garnizon) ile bağ 791’de koptu; Hotan’ın fiilî düşüş yılı okunmadı. TDV Hoten 744’ten itibaren Hoten’i Uygur Kağanlığı sınırlarında sayar → bu yüzden ÇELİŞKİ: aşağıdaki dilim TDV’yi (esas) izler; 744-791 arası Çin kaynağında Tang garnizonu görünür.",
