  "kaynak": "TDV İslâm Ansiklopedisi, «Merv» md., https://islamansiklopedisi.org.tr/merv (22.10.2026'da okundu): «Abbâsî ihtilâli Merv’de patlak verdi. Ebû Müslim-i Horasânî 129’da (747) Araplar’dan çok İranlı köylülerle diğer mevâlîden oluşturduğu ordusunun başında şehre girdiğinde çarpışmayı göze alamayan Emevîler’in son Horasan valisi Nasr b. Seyyâr ailesiyle birlikte kaçmayı tercih etti» | TDV İslâm Ansiklopedisi, «Serahs» md., https://islamansiklopedisi.org.tr/serahs (22.10.2026'da okundu): «Eyalet merkezi Merv’i Ebû Müslim’e bırakmak zorunda kalan Nasr (9 Cemâziyelevvel 130 / 15 Ocak 748)» | ÇELİŞKİ/BEYAN: Merv’in Ebû Müslim eline geçişi TDV Merv’de 129/747, TDV Serahs’ta 15 Ocak 748 (gün). Abbâsî künyesi f=0749-11-28 olduğundan (künye hayalet olmasın) dilim bitişi 750-01-01 yıl hassasiyetiyle yazıldı (diğer Horasan şehirleriyle aynı); gerçek devir 747/748. Künye düzeltme önerisi: abbasi f→747-06 (Abbâsî ihtilâli) ya da bu dilimi “Abbâsî ihtilâli” kimliğine bağlamak.",
